if (ctx._source.grouped_data.size() == 2) {
  // Compare the two objects
  def first = ctx._source.grouped_data[0].data;
  def second = ctx._source.grouped_data[1].data;

  if (first.equals(second)) {
    // Remove the field if both objects are identical
    ctx._source.remove("grouped_data");
    ctx._source.remove("unique_field");
    ctx._source.to_delete = true;
  } else {
    // Find differences between the objects
    def differences_a = [:];
    def differences_b = [:];
    differences_a.put("index_name", ctx._source.grouped_data[0].source_index);
    differences_b.put("index_name", ctx._source.grouped_data[1].source_index);
    for (entry in first.entrySet()) {
      if (!second.containsKey(entry.getKey()) || second[entry.getKey()] != entry.getValue()) {
        differences_a.put(entry.getKey(), entry.getValue());
      }
    }
    for (entry in second.entrySet()) {
      if (!first.containsKey(entry.getKey()) || first[entry.getKey()] != entry.getValue()) {
        differences_b.put(entry.getKey(), entry.getValue());
      }
    }
    ctx._source.grouped_data = [differences_a,differences_b];
  }
}
